#include <iostream>
#include <vector>
#include <unordered_set>

using namespace std;

bool is_prime(long long n) {
    if (n < 2) return false;
    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;

    vector<long long> P(N);
    unordered_set<long long> s;
    bool has_two = false;

    for (int i = 0; i < N; ++i) {
        cin >> P[i];
        s.insert(P[i]);
        if (P[i] == 2) has_two = true;
    }

    if (!has_two) {
        cout << "TIDAK ADA\n";
        return 0;
    }

    bool found = false;
    for (int i = 0; i < N; ++i) {
        if (P[i] != 2 && s.count(P[i] + 2) && is_prime(P[i] + 2)) {
            found = true;
            break;
        }
    }

    cout << (found ? "ADA" : "TIDAK ADA") << "\n";
    return 0;
}

