    long long term1 = (N + 1) * (M + 1) % 1000000007; // atau tanpa modulo jika batas fit di __int128
    // Menggunakan __int128_t untuk menghindari overflow perkalian
    __int128 n = N, m = M, k = K;
    __int128 sum_1 = k;
    __int128 sum_k = k * (k + 1) / 2;
    __int128 sum_k2 = k * (k + 1) * (2 * k + 1) / 6;

    __int128 total = (n + 1) * (m + 1) * sum_1 - (n + m + 2) * sum_k + sum_k2;

